-- Carga del calendario de máquinas (dbo.UrdEngCalMaquinas) del 1-ene al 16-oct-2026 según los avisos de
-- Dirección (CalUrdEng.xlsx: horas programadas por día y turno, iguales para todas las máquinas).
-- Generado del Excel. Reemplaza a carga_UrdEngCalMaquinas_2026.sql (plantilla 24/7): no correr esa
-- después de esta, porque llenaría con turnos los días sin programa (festivos, paros, fines de semana sin aviso).
--
-- Máquinas por MaquinaId (el Id cambia entre bases): Urdido → Mc Coy 1-3; Urdido KM → KM1;
-- Engomado WP2 / WP3 → WestPoint 2 / WestPoint 3.
-- Reglas:
-- - 1er/2do/3er turno = 06:30 / 14:30 / 22:30 con las horas del Excel (8 h = 480 min); 0 = sin fila.
--   Turno = cuadrilla según UrdEngCalMaquina::ROTACION_URDIDO.
-- - 12×12: 06:30–18:30 y 18:30–06:30 (720 min); Turno = la columna que trabaja (1er/2do/3er).
-- - Sin aviso pero las checadas muestran que se trabajó (ago–sep): 8 h en cada turno con 4 h o más de personal.
-- - Fin de semana o festivo sin aviso: sin filas, igual que el Excel. (Hasta el 22-oct-2026 se cargaba el
--   1er turno de los 7 sábados sin aviso como "regla base", que el Excel no respalda; se quitó.)
-- Se puede correr más de una vez: no inserta un turno que ya exista (Maquina, FechaInicio).
-- Compatible con SQL Server 2008 R2. Esperado en una tabla vacía: 4710 filas.

SET NOCOUNT ON;
SET XACT_ABORT ON;

IF (SELECT COUNT(*) FROM dbo.URDCatalogoMaquinas WHERE MaquinaId IN (N'KM1', N'Mc Coy 1', N'Mc Coy 2', N'Mc Coy 3', N'WestPoint 2', N'WestPoint 3')) <> 6
BEGIN
    RAISERROR(N'Faltan máquinas en URDCatalogoMaquinas (KM1, Mc Coy 1, Mc Coy 2, Mc Coy 3, WestPoint 2, WestPoint 3). No se cargó nada.', 16, 1);
    RETURN;
END;

